const operationsMode=location.pathname.startsWith('/operations');
const BRAND='Nook';
let customer=null,pendingLogin=null,loginNext='account';
try{const saved=JSON.parse(localStorage.getItem('nook-customer-v1'));if(saved && typeof saved.name==='string' && /^[6-9][0-9]{9}$/.test(saved.phone))customer=saved}catch{}
const seed=[['Farm-fresh bananas','6 pieces','Fruit & veg',48,60,'🍌'],['Red tomatoes','500 g','Fruit & veg',24,30,'🍅'],['Fresh toned milk','500 ml','Dairy & eggs',28,30,'🥛'],['Whole wheat bread','400 g','Bakery',45,50,'🍞'],['Farm white eggs','6 pieces','Dairy & eggs',54,65,'🥚'],['Hass avocado','1 piece','Fruit & veg',89,110,'🥑'],['Shimla apples','500 g','Fruit & veg',99,120,'🍎'],['Fresh broccoli','1 piece · 250 g','Fruit & veg',59,75,'🥦'],['Salted butter','100 g','Dairy & eggs',60,62,'🧈'],['Chocolate cookies','150 g','Snacks',35,40,'🍪'],['Classic potato chips','52 g','Snacks',20,20,'🍟'],['Orange juice','1 litre','Drinks',110,130,'🧃'],['Premium basmati rice','1 kg','Pantry',129,160,'🍚'],['Whole wheat atta','5 kg','Pantry',245,280,'🌾'],['Sunflower oil','1 litre','Pantry',145,165,'🌻'],['Filter coffee','200 g','Drinks',180,210,'☕'],['Soft tissue rolls','4 rolls','Home care',99,120,'🧻'],['Dishwash liquid','500 ml','Home care',95,110,'🧴'],['Butter croissant','2 pieces','Bakery',89,100,'🥐'],['Fresh paneer','200 g','Dairy & eggs',85,95,'🧀']].map((p,id)=>({id,name:p[0],unit:p[1],category:p[2],price:p[3],mrp:p[4],emoji:p[5],stock:id===17?0:24}));
const defaults={products:seed,cart:{},radius:8,address:{label:'Home',line:'12, 2nd Main, Indiranagar, Bengaluru',distance:2.4},orders:[]};let state;try{state=JSON.parse(localStorage.getItem('nook-demo-v1'))||structuredClone(defaults)}catch{state=structuredClone(defaults)}let category='All essentials',query='',view='shop',payment='Cash on delivery',currentOrder=null;const statuses=['Confirmed','Packing','Out for delivery','Delivered'];
const $=s=>document.querySelector(s),money=n=>'₹'+n.toLocaleString('en-IN'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('nook-demo-v1',JSON.stringify(state));updateHeader()}function count(){return Object.values(state.cart).reduce((a,b)=>a+b,0)}function subtotal(){return state.products.reduce((s,p)=>s+p.price*(state.cart[p.id]||0),0)}function fee(){return subtotal()>=299?0:25}function eligible(){return state.address.distance<=state.radius}function updateHeader(){$('#accountButton').textContent=customer?'My account':'Log in';$('#cartLabel').textContent=count()?`${count()} items · ${money(subtotal())}`:'My basket';$('#addressLabel').textContent=`⌖ ${state.address.label} · ${state.address.distance} km ⌄`}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function qty(p){let n=state.cart[p.id]||0;return n?`<div class="quantity"><button aria-label="Remove one ${esc(p.name)}" onclick="change(${p.id},-1)">−</button><span>${n}</span><button aria-label="Add one ${esc(p.name)}" onclick="change(${p.id},1)" ${n>=p.stock?'disabled':''}>+</button></div>`:`<button class="add" onclick="change(${p.id},1)" ${!p.stock?'disabled':''}>${p.stock?'ADD +':'Sold out'}</button>`}
function change(id,d){let p=state.products[id],n=(state.cart[id]||0)+d;if(n>p.stock){toast('No more stock available');return}if(n<=0)delete state.cart[id];else state.cart[id]=n;save();if(view==='shop')render();if($('#dialog').open&&$('#dialogContent').dataset.kind==='cart')showCart()}
function render(){view='shop';let products=state.products.filter(p=>(category==='All essentials'||p.category===category)&&`${p.name} ${p.category}`.toLowerCase().includes(query.toLowerCase()));$('#main').innerHTML=`<div class="heading"><div><h1>A little of everything. Nearby.</h1><p>Your daily essentials, from your local favourite.</p></div><span class="pill">◷ 25–35 min</span></div>${!query?`<section class="hero"><div class="hero-copy"><span class="eyebrow">FRESH FINDS. EVERY DAY.</span><h2>Good food.<br>Great neighbours.</h2><p>Fresh picks and pantry favourites,<br>right at your doorstep.</p><button onclick="selectCategory('Fruit & veg')">Shop fresh picks ↗</button></div><img src="grocery.jpg" alt="A basket filled with fresh vegetables and fruit"></section>`:''}<div class="categories">${['All essentials','Fruit & veg','Dairy & eggs','Bakery','Snacks','Drinks','Pantry','Home care'].map((c,i)=>`<button class="category ${category===c?'active':''}" onclick="selectCategory('${c}')">${['✦','🥬','🥛','🥐','🍿','☕','🌾','🧺'][i]} ${c}</button>`).join('')}</div><div class="section-title"><h2>${query?'Search results':category==='All essentials'?'Your everyday favourites':category}</h2><small>${products.length} essentials · thoughtfully picked</small></div><div class="grid">${products.map(p=>`<article class="product">${p.price<p.mrp?`<span class="badge">${Math.round((1-p.price/p.mrp)*100)}% OFF</span>`:''}<div class="product-art" role="img" aria-label="${esc(p.name)} illustration"><span>${p.emoji}</span></div><span class="time">◷ 25–35 MINS</span><h3>${esc(p.name)}</h3><div class="unit">${esc(p.unit)}</div><div class="buyrow"><span class="price">${money(p.price)} ${p.price<p.mrp?`<del>${money(p.mrp)}</del>`:''}</span>${qty(p)}</div></article>`).join('')}</div>${!products.length?'<div class="empty">No essentials found. Try “milk”, “rice” or another category.</div>':''}${count()?`<button class="primary mobile-basket" onclick="showCart()">${count()} items · ${money(subtotal())} <span style="float:right">View basket →</span></button>`:''}<div class="benefits"><span>✧ <b>Picked with care</b> &nbsp; Quality in every bag</span><span>⌖ <b>Always local</b> &nbsp; One store. Your neighbourhood.</span><span>♧ <b>Small basket, big joy</b> &nbsp; Free delivery over ₹299</span></div><footer>${BRAND} · Indiranagar, Bengaluru &nbsp; / &nbsp; Interactive demo · No real orders or payments<br><button class="link" style="margin-top:14px" onclick="showOrders()">My orders</button></footer>`;updateHeader()}
function selectCategory(c){category=c;query='';$('#search').value='';render()}
function modal(title,body,kind='other'){$('#dialogContent').dataset.kind=kind;$('#dialogContent').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="$('#dialog').close()">×</button></div><div class="modal-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal()}
function bill(){return `<div class="row"><span>Item total</span><span>${money(subtotal())}</span></div><div class="row"><span>Delivery</span><span>${fee()?money(fee()):'FREE'}</span></div><div class="row total"><span>To pay</span><span>${money(subtotal()+fee())}</span></div>`}
function showCart(){modal('Your basket',count()?`<div class="notice">${fee()?`Add ${money(299-subtotal())} more for free delivery.`:'Your delivery is on us. A little neighbourhood perk.'}</div>${state.products.filter(p=>state.cart[p.id]).map(p=>`<div class="row cart-item"><span class="emoji">${p.emoji}</span><div class="info"><strong>${esc(p.name)}</strong><small>${esc(p.unit)} · ${money(p.price*state.cart[p.id])}</small></div>${qty(p)}</div>`).join('')}${bill()}<button class="primary full" onclick="checkout()">Continue to checkout →</button>`:'<div class="empty">Your next good meal starts here.<br>Your basket is empty.</div><button class="primary full" onclick="$(\'#dialog\').close()">Explore the store</button>','cart')}
function addressNotice(){return `<div class="notice ${eligible()?'':'error'}">${eligible()?'✓ You’re in our neighbourhood':'Outside our delivery area'} · ${state.address.distance} km from store<br>We currently deliver within ${state.radius} km.</div>`}
function showAddress(){modal('Where should we deliver?',`<p style="color:var(--muted);font-size:14px">Select a demo address or add your own.</p>${[['Home','12, 2nd Main, Indiranagar, Bengaluru',2.4],['Office','42, 100 Feet Road, Domlur, Bengaluru',5.6],['Outside delivery area','7, Whitefield Main Road, Bengaluru',10.2]].map((a,i)=>`<button class="address-choice" onclick="pickAddress(${i})"><strong>⌖ ${a[0]} · ${a[2]} km</strong><small>${a[1]}</small></button>`).join('')}<form onsubmit="saveAddress(event)"><label class="field">Address<input name="line" required maxlength="180" placeholder="Flat, building, street, neighbourhood"></label><label class="field">Demo distance from store (km)<input name="distance" type="number" min="0" max="100" step="0.1" value="3" required></label><p style="font-size:12px;color:var(--muted)">Distances are simulated for this demo; no live location is used.</p><button class="primary full">Use this address</button></form>`)}
function pickAddress(i){let a=[['Home','12, 2nd Main, Indiranagar, Bengaluru',2.4],['Office','42, 100 Feet Road, Domlur, Bengaluru',5.6],['Outside area','7, Whitefield Main Road, Bengaluru',10.2]][i];state.address={label:a[0],line:a[1],distance:a[2]};save();$('#dialog').close();toast(eligible()?'Address updated — delivery available':'Address updated — outside delivery area')}
function saveAddress(e){e.preventDefault();let f=new FormData(e.target);state.address={label:'Custom address',line:f.get('line').trim(),distance:Number(f.get('distance'))};if(!state.address.line)return;save();$('#dialog').close();toast('Delivery address updated')}
function checkout(){if(!count())return showCart();if(!customer)return showLogin('checkout');modal('One last thing…',`<div class="row"><strong>Deliver to ${esc(state.address.label)}</strong><button class="link" onclick="showAddress()">Change</button></div><p style="font-size:14px">${esc(state.address.line)}</p>${addressNotice()}<label class="field">Payment method<select onchange="payment=this.value"><option ${payment==='Cash on delivery'?'selected':''}>Cash on delivery</option><option ${payment==='UPI (demo)'?'selected':''}>UPI (demo)</option><option ${payment==='Card (demo)'?'selected':''}>Card (demo)</option></select></label><div class="notice">This is a demo. No payment will be collected and no order will be sent to a real store.</div>${bill()}<button class="primary full" onclick="placeOrder()" ${!eligible()?'disabled':''}>Place demo order · ${money(subtotal()+fee())}</button>`,'checkout')}
function placeOrder(){if(!customer)return showLogin('checkout');if(!eligible()||!count())return;for(let p of state.products)if((state.cart[p.id]||0)>p.stock){toast(`${p.name} has insufficient stock. Update your basket.`);return showCart()}let o={id:'NK-'+String(Date.now()).slice(-6),created:new Date().toISOString(),customer:{...customer},items:state.products.filter(p=>state.cart[p.id]).map(p=>({name:p.name,qty:state.cart[p.id],price:p.price})),total:subtotal()+fee(),address:{...state.address},payment,status:0};for(let p of state.products)p.stock-=state.cart[p.id]||0;state.orders.unshift(o);state.cart={};save();render();modal('You’re all set!',`<div class="center"><div class="success-icon">✓</div><h2>Good things are on the way.</h2><p>Your neighbourhood store has received<br>order <strong>${o.id}</strong>.</p><div class="notice">Estimated arrival · 25–35 minutes<br>${esc(o.address.line)}</div><button class="primary full" onclick="track('${o.id}')">Track my order →</button><p style="font-size:12px;color:var(--muted)">Demo order · ${esc(payment)} · ${money(o.total)}</p></div>`)}
function showOrders(){if(!customer)return showLogin('orders');const orders=state.orders.filter(o=>o.customer?.phone===customer.phone);modal('Your orders',orders.length?orders.map(o=>`<div class="order-card"><div class="row"><strong>${o.id}</strong><span>${money(o.total)}</span></div><p style="font-size:13px;color:var(--muted)">${o.items.reduce((s,i)=>s+i.qty,0)} items · ${new Date(o.created).toLocaleDateString('en-IN')} · ${statuses[o.status]}</p><button class="secondary" onclick="track('${o.id}')">View & track →</button></div>`).join(''):'<div class="empty">No orders yet. Your favourites are waiting.</div>')}
function track(id){let o=state.orders.find(o=>o.id===id);if(!o)return;if(view!=='admin'&&(!customer||o.customer?.phone!==customer.phone))return showOrders();currentOrder=id;modal('Your neighbourhood delivery',`<div class="notice">${o.status===3?'✓ Delivered. Enjoy your essentials!':'◷ '+(o.status===2?'Arriving in 5–10 minutes':'Estimated arrival · 25–35 minutes')}<br>Order ${o.id}</div><div class="timeline" style="margin-top:20px">${statuses.map((s,i)=>`<div class="step ${i<=o.status?'done':''}"><i>${i<=o.status?'✓':i+1}</i><div><strong>${s}</strong><small>${['Your store has received the order','We’re picking your essentials','Your rider is heading your way','Handed over at your doorstep'][i]}</small></div></div>`).join('')}</div><strong>Delivering to ${esc(o.address.label)}</strong><p style="font-size:14px">${esc(o.address.line)}</p><details><summary>Order details · ${money(o.total)}</summary>${o.items.map(i=>`<div class="row"><span>${i.qty} × ${esc(i.name)}</span><span>${money(i.price*i.qty)}</span></div>`).join('')}<p>${esc(o.payment)}</p></details><p style="font-size:12px;color:var(--muted)">Simulated tracking. Update order progress in Store demo.</p><button class="secondary full" onclick="$('#dialog').close();showAdmin()">Open store demo</button>`,'tracking')}
function showAdmin(){location.href='/operations/'}
function setRadius(e){e.preventDefault();state.radius=Number(new FormData(e.target).get('radius'));save();toast(`Delivery radius updated to ${state.radius} km`)}function editProduct(id,key,input){if(!input.checkValidity()){input.reportValidity();input.value=state.products[id][key];return}state.products[id][key]=Number(input.value);if(key==='price')state.products[id].mrp=Math.max(state.products[id].mrp,Number(input.value));save();showAdmin();toast('Product updated')}function updateStatus(id,n){let o=state.orders.find(o=>o.id===id);if(Number(n)<o.status)return;o.status=Number(n);save();showAdmin();toast('Order status updated')}
$('#search').addEventListener('input',e=>{query=e.target.value;render()});$('.brand').addEventListener('click',e=>{if(operationsMode)return;e.preventDefault();category='All essentials';query='';$('#search').value='';render()});window.addEventListener('storage',e=>{if(e.key==='nook-demo-v1'){try{state=JSON.parse(e.newValue);updateHeader();if(operationsMode){if(typeof renderOps==='function')renderOps()}else render();if($('#dialog').open&&$('#dialogContent').dataset.kind==='tracking')track(currentOrder)}catch{}}});if(!operationsMode)render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_products',description:'Filter the visible store catalog by product name or category.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.query!=='string'||input.query.length>100)throw new Error('Query must be a string of at most 100 characters');query=input.query;category='All essentials';$('#search').value=query;render();return{products:state.products.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(query.toLowerCase())).map(p=>({id:p.id,name:p.name,price:p.price,stock:p.stock}))}}})).catch(()=>{})}catch{}}

function showLogin(next='account'){
 loginNext=next;pendingLogin=null;
 modal('Welcome to the neighbourhood',`<div class="auth-intro"><span class="auth-mark">n.</span><p>Your everyday essentials,<br>a little closer.</p></div><div class="notice">Demo login only. Use a sample mobile number. No SMS is sent.</div><form onsubmit="requestDemoOtp(event)"><label class="field">Your name<input name="name" autocomplete="name" required maxlength="50" placeholder="e.g. Alex"></label><label class="field">Mobile number<div class="phone-field"><span>+91</span><input name="phone" type="tel" inputmode="numeric" autocomplete="tel-national" pattern="[6-9][0-9]{9}" minlength="10" maxlength="10" required placeholder="9876543210" title="Enter a 10-digit Indian mobile number starting with 6, 7, 8 or 9"></div></label><p id="loginError" class="auth-error" role="alert"></p><button class="primary full">Continue →</button><p class="auth-note">Your profile is stored only in this browser. This does not create a real account.</p></form>`,'login');
}
function requestDemoOtp(e){
 e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),phone=String(f.get('phone')||'').trim();
 if(!name||name.length>50||!/^[6-9][0-9]{9}$/.test(phone)){$('#loginError').textContent='Enter your name and a valid 10-digit mobile number.';return}
 pendingLogin={name,phone};showOtp();
}
function showOtp(){
 if(!pendingLogin)return showLogin(loginNext);
 modal('One small step',`<p>Continue with +91 ${esc(pendingLogin.phone)} <button class="link" onclick="showLogin(loginNext)">Change</button></p><div class="notice">No SMS is sent. Your demo code is <strong>123456</strong>.</div><form onsubmit="verifyDemoOtp(event)"><label class="field">6-digit demo code<input class="otp-input" name="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required placeholder="000000"></label><p id="loginError" class="auth-error" role="alert"></p><button class="primary full">Log in${loginNext==='checkout'?' & continue to checkout':''} →</button></form><p class="auth-note">For presentation only. This code does not verify ownership of a mobile number.</p>`,'login');
}
function verifyDemoOtp(e){
 e.preventDefault();if(!pendingLogin)return showLogin(loginNext);
 if(String(new FormData(e.target).get('otp'))!=='123456'){$('#loginError').textContent='That code didn’t match. Enter the demo code 123456.';return}
 customer={...pendingLogin};pendingLogin=null;localStorage.setItem('nook-customer-v1',JSON.stringify(customer));updateHeader();toast('Welcome, '+customer.name+'!');if(loginNext==='checkout')checkout();else if(loginNext==='orders')showOrders();else showAccount();
}
function showAccount(){
 if(!customer)return showLogin();
 modal('Your Nook account',`<div class="auth-intro"><span class="auth-mark">${esc(customer.name.charAt(0).toUpperCase())}</span><div><h3>${esc(customer.name)}</h3><p>+91 ${esc(customer.phone)}</p></div></div><div class="notice">Demo profile · Saved on this browser only</div><button class="secondary full" onclick="showOrders()">My orders →</button><button class="secondary full" onclick="showAddress()">Delivery address →</button><button class="primary full" onclick="logout()">Log out</button>`,'account');
}
function logout(){customer=null;pendingLogin=null;localStorage.removeItem('nook-customer-v1');$('#dialog').close();updateHeader();toast('You’re logged out. Your basket is saved.');}
window.addEventListener('storage',e=>{if(e.key==='nook-customer-v1'){try{const saved=JSON.parse(e.newValue);customer=saved&&typeof saved.name==='string'&&/^[6-9][0-9]{9}$/.test(saved.phone)?saved:null}catch{customer=null}pendingLogin=null;$('#dialog').close();updateHeader();}});
